export function createScene({kit,config,tokens}){const k=kit.illustration,s=k.createStage({width:600,height:400,bounds:k.boxBounds([-45,-45,-15],[45,45,65]),config,tokens});const support=k.box('support',{width:20,depth:20,height:40});support.position.z=25;s.scene.add(support);const marker=kit.effects.effect('marker',{kind:'glow',size:[12,12,1],theme:config.theme});support.add(marker);const fallback=kit.effects.fallback(k.cylinder('marker-vector',{radius:2,height:.2,tone:'accent'}),'marker');s.scene.add(fallback);
 const view=s.camera.position.clone().normalize(),right=new k.Vector3(-view.y,view.x,0).normalize();function update({time}){marker.position.set(0,0,0).addScaledVector(view,(time-1)*32).addScaledVector(right,Math.sin(Math.PI*time/2)*19);fallback.position.copy(marker.position).add(support.position);return {reading:`Depth crossing ${time.toFixed(2)}`};}return {...s,update,support,marker};}
